package cn.minidayz.patcher;
import java.net.*;import org.json.*;
/** Provider-neutral wire formats. No paid-call retries or automatic model guessing. */
public final class ApiProtocol {
 public static String mode(String url,String choice){if(!choice.equals("auto"))return choice;String u=url.toLowerCase(java.util.Locale.US);if(u.endsWith("/responses"))return "responses";if(u.endsWith("/messages"))return "anthropic";return "chat";}
 public static String endpoint(String raw,String choice)throws Exception{String s=raw.trim();while(s.endsWith("/"))s=s.substring(0,s.length()-1);URL u=new URL(s);FilesEx.require("https".equals(u.getProtocol())&&u.getHost().length()>0&&u.getUserInfo()==null&&u.getQuery()==null&&u.getRef()==null,"E_AI_URL: 请填写无查询参数的 HTTPS 基础地址或完整地址");String tail=mode(s,choice).equals("responses")?"/responses":mode(s,choice).equals("anthropic")?"/messages":"/chat/completions";for(String suffix:new String[]{"/chat/completions","/responses","/messages"})if(s.endsWith(suffix))return s.substring(0,s.length()-suffix.length())+tail;if(u.getPath().length()==0)s+="/v1";return s+tail;}
 public static String modelsUrl(String raw)throws Exception{String s=endpoint(raw,"auto");for(String suffix:new String[]{"/chat/completions","/responses","/messages"})if(s.endsWith(suffix))s=s.substring(0,s.length()-suffix.length());return s+"/models";}
 public static JSONObject body(String mode,String model,JSONArray messages,int limit,String tokenField)throws Exception{FilesEx.require(model.trim().length()>0&&!model.trim().equalsIgnoreCase("go"),"E_AI_MODEL: 请填写具体模型 ID；go 是套餐名称，不是模型");JSONObject b=new JSONObject().put("model",model).put("stream",false);if(mode.equals("responses")){JSONArray input=new JSONArray();for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);input.put(new JSONObject().put("role",m.getString("role")).put("content",m.getString("content")));}return b.put("input",input).put("max_output_tokens",limit);}if(mode.equals("anthropic")){String system="";JSONArray items=new JSONArray();for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);if(m.getString("role").equals("system"))system+=m.getString("content")+"\n";else items.put(new JSONObject().put("role",m.getString("role")).put("content",m.getString("content")));}b.put("messages",items).put("max_tokens",limit);if(system.length()>0)b.put("system",system);return b;}return b.put("messages",messages).put(tokenField,limit);}
 public static String text(JSONObject r,String mode)throws Exception{StringBuilder s=new StringBuilder();if(mode.equals("responses")){if(r.has("output_text"))s.append(r.optString("output_text"));else{JSONArray a=r.optJSONArray("output");if(a!=null)for(int i=0;i<a.length();i++){JSONArray c=a.getJSONObject(i).optJSONArray("content");if(c!=null)for(int k=0;k<c.length();k++)if(c.getJSONObject(k).optString("type").equals("output_text"))s.append(c.getJSONObject(k).optString("text"));}}}else if(mode.equals("anthropic")){JSONArray a=r.optJSONArray("content");if(a!=null)for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("type").equals("text"))s.append(a.getJSONObject(i).optString("text"));}else{JSONArray a=r.optJSONArray("choices");FilesEx.require(a!=null&&a.length()>0,"E_AI_RESPONSE: 接口未返回 choices，请核对协议");Object c=a.getJSONObject(0).getJSONObject("message").opt("content");if(c instanceof String)s.append((String)c);else if(c instanceof JSONArray){JSONArray parts=(JSONArray)c;for(int i=0;i<parts.length();i++)s.append(parts.getJSONObject(i).optString("text"));}}FilesEx.require(s.length()>0&&s.length()<=160000,"E_AI_RESPONSE: 未收到可见文本或响应过大；请检查协议、模型或增加输出上限");return s.toString();}
 public static String error(int status,String raw,String key){String detail=raw;try{JSONObject r=new JSONObject(raw);Object e=r.opt("error");if(e instanceof JSONObject)detail=((JSONObject)e).optString("message",((JSONObject)e).toString());else if(e!=null)detail=e.toString();else detail=r.optString("message",raw);}catch(Exception ignored){detail=raw.replaceAll("<[^>]+>"," ");}detail=AiClient.redact(detail,key).replaceAll("[\\r\\n]+"," ");if(detail.length()>1200)detail=detail.substring(0,1200);String hint=status==401?"密钥无效或未获授权":status==403?"平台权限、地区或客户端限制":status==404?"请求地址或模型不存在":status==429?"额度不足或请求限速":status>=500?"平台服务异常":"协议、模型或请求参数不匹配";return "E_AI_HTTP: HTTP "+status+" · "+hint+"\n平台返回："+detail+"\n未自动重试。";}
}
